def process(boston_data) -> pd.DataFrame:
    df = boston_data[boston_data['Year'] == '2020'].copy()
    if len(df) > 0:
        jun = pd.to_numeric(df['Jun'].iloc[0], errors='coerce')
        jul = pd.to_numeric(df['Jul'].iloc[0], errors='coerce')
        aug = pd.to_numeric(df['Aug'].iloc[0], errors='coerce')
        total = jun + jul + aug
        return pd.DataFrame({'Region': ['Boston'], 'Jun': [jun], 'Jul': [jul], 'Aug': [aug], 'Total': [total]})
    return pd.DataFrame({'Region': ['Boston'], 'Jun': [None], 'Jul': [None], 'Aug': [None], 'Total': [None]})

