def process(boston_2020_summer, chatham_2020_summer, amherst_2020_summer, ashburnham_2020_summer) -> pd.DataFrame:
    combined = pd.concat([boston_2020_summer, chatham_2020_summer, amherst_2020_summer, ashburnham_2020_summer], ignore_index=True)
    max_region = combined.loc[combined['Total'].idxmax()]
    return pd.DataFrame([{'Region': max_region['Region'], 'Total_Rainfall': max_region['Total']}])
